  if (aNonposInt && s > 0.0) { return _gpu_inf(); } // (a+k) = 0 diverges
  if (a < 0.0 && s != floor(s)) { return _gpu_nan(); } // complex value
  if (a < -1.0e6) { return _gpu_nan(); }
